export interface HistoryEntry {
  run_id: Id;
  command_id: Id;
  command_type: null | CommandType;
  started_wall_utc: NullableWallUtc;
  finished_wall_utc: NullableWallUtc;
  outcome: null | RunOutcome;
  exit_status: number | null;
  evidence_complete: boolean | null;
  evidence_gaps: number | null;
  artifact_digest: NullableDigest;
  adopted: boolean;
  data_mode?: NullableDataMode;
  bundle_digest?: NullableDigest;
}
