export interface SnapshotLatestRetainedObservation {
  observation_id: Id;
  source_role: 'wrist' | 'front' | 'base' | 'other';
  media: 'frame' | 'frame_pair';
  width_px: number | null;
  height_px: number | null;
  content_digest: NullableDigest;
  source_stamp: null | SourceStamp;
  retained: boolean;
  seq: number;
  t_wall_utc: NullableWallUtc;
}
/**
 * The newest measured.state record of this runtime session, named with exactly the fields that record carries: its whole payload, plus the two the envelope carries and the payload cannot, which are the record's own sequence number in the ordered log and the wall time the runtime wrote on it. A consumer folds this and a folded measured.state record into one shape and decides between them by seq, so it never has to decide which of two descriptions of the same reading to believe. t_wall_utc is when the RECORD WAS WRITTEN by the runtime. It is not the instant the servo bus was sampled: relating the two needs a clock relation nothing here supplies, so a consumer that prints an age says which of the two it is counting from.
 */
export interface SnapshotLatestMeasuredState {
  joints: MeasuredJoints;
  base_velocity: MeasuredBaseVelocity;
  consumed_source_stamp: SourceStamp;
  seq: number;
  t_wall_utc: NullableWallUtc;
}
/**
 * Evidence completeness of the session so far.
 */
export interface SnapshotEvidence {
  complete: boolean;
  gaps: number;
  dropped_telemetry: number;
}
/**
 * The pixel size of the frame this slot carries. A consumer that draws over the picture needs it, and a slot without it draws nothing.
 */
export interface PreviewFrameSize {
  width_px: number | null;
  height_px: number | null;
}
/**
 * What the camera preview is doing, and the last frame it delivered. THE AGE OF THE PICTURE CANNOT BE COMPUTED HERE: capture_clock is the source's monotonic clock and receive_mono_ns is the laptop's, so capture_age_ms is null and capture_age_reason says why. What can be measured inside ONE clock is measured: service_latency_ms is capture to dequeue on the source, and capture_time_stalls counts a capture clock that stopped moving. Optional extension: clock_relation is the only thing that would license a capture age, and is null until one is measured; skipped_for_mission counts the previews the camera service stood aside for while a decision capture was in flight, which is the source YIELDING and not a stall; bytes_b64 carries the latest picture on the transport that serves it and is stripped from the console's copy.
 */
export interface PreviewSlot {
  available: boolean;
  state: SourceState;
  reason: NullableReasonCode;
  role: Id;
  seq: number | null;
  source_seq: number | null;
  capture_clock: null | SourceStamp;
  capture_semantics: NullableId;
  capture_age_ms: number | null;
  capture_age_reason: NullableReasonCode;
  service_latency_ms: number | null;
  receive_mono_ns: number | null;
  receive_age_ms: number | null;
  measured_fps: number | null;
  frame: null | PreviewFrameSize;
  stream: PreviewStream;
  gaps: number | null;
  session_changes: number | null;
  capture_time_stalls: number | null;
  malformed: number | null;
  skipped_for_mission?: number | null;
  clock_relation?: null | ClockRelation;
  bytes_b64?: string;
}
/**
 * What the camera service said about the stream the preview is taken from. Every field is what the source reported, and null where it reported nothing.
 */
export interface PreviewStream {
  pixel_format: string | null;
  source_fps_reported: number | null;
  source_fps_measured: number | null;
  source_width: number | null;
  source_height: number | null;
}
/**
 * Which clock each half of a slot was read from. sample is the source's own; receive is this runtime's. Nothing subtracts one from the other.
 */
export interface SourceClockDomains {
  sample: ClockDomain;
  receive: ClockDomain;
}
/**
 * The host's own lease report as the tap passed it on. It is what the HOST says, which is not what the runtime holds: the snapshot's lease is the runtime's answer to that question. The request id an acquisition is adopted by is deliberately not here and never leaves the host process.
 */
export interface TapLease {
  state: string | null;
  host_session: string | null;
  generation: number | null;
  owner_label: string | null;
  ttl_s: number | null;
  expires_in_ms: number | null;
  acquisitions: number | null;
  releases: number | null;
  expiries: number | null;
}
/**
 * What the host observation tap is doing, and the last sample it delivered. source_stamp, joints and base_velocity are the host's own values, passed through with the host's session, sequence number and monotonic sample time; everything this runtime measured (receive_mono_ns, receive_age_ms, measured_rate_hz) is the laptop's clock and clock_domains names both. A stalled slot keeps the LAST stamp and how long ago it arrived, and reports no values.
 */
export interface TapSlot {
  available: boolean;
  state: SourceState;
  reason: NullableReasonCode;
  source_stamp: null | SourceStamp;
  joints: null | MeasuredJoints;
  base_velocity: null | MeasuredBaseVelocity;
  receive_mono_ns: number | null;
  receive_age_ms: number | null;
  clock_domains: SourceClockDomains;
  measured_rate_hz: number | null;
  subscriber_gap_count: number | null;
  publisher_drop_count: number | null;
  session_changes: number | null;
  malformed_count: number | null;
  transport_errors: number | null;
  lease: null | TapLease;
  rejections: SourceCounters;
  commands: SourceCounters;
  ingestion: SourceCounters;
}
